INSERT INTO cw_invoice_request (tenant_id, order_id, invoice_title, status, created_at_ms)
SELECT #{record.tenantId}, o.order_id, #{record.invoiceTitle}, #{record.status}, #{record.createdAtMs}
FROM cw_order o
WHERE o.tenant_id = #{record.tenantId}
  AND CAST(o.user_id AS BINARY) = CAST(#{userId} AS BINARY) AND o.order_id = #{record.orderId}
